mapper.select:
SELECT u.user_sq AS userSq, u.user_type_cd AS userType, u.user_email AS email, u.user_nm AS userNm, c.company_nm AS companyNm, u.user_phone_num AS phone, s.sanction_count AS sanctionCount, s.report_sq AS reportSq, s.sanction_type_cd AS sanctionStatus, s.sanction_reason_txt AS sanctionReason, DATE_FORMAT(s.sanction_end_dtm, '%Y-%m-%d %H:%i:%s') AS suspendedUntilDtm FROM tbl_user_m u INNER JOIN tbl_user_sanction_h s ON u.user_sq = s.user_sq LEFT JOIN tbl_company_s c ON u.user_sq = c.user_sq WHERE s.sanction_is_active_yn = 'Y'
AND (u.user_nm LIKE CONCAT('%', #{searchKeyword}, '%') OR u.user_email LIKE CONCAT('%', #{searchKeyword}, '%') OR u.user_phone_num LIKE CONCAT('%', #{searchKeyword}, '%') OR c.company_nm LIKE CONCAT('%', #{searchKeyword}, '%'))
AND u.user_type_cd = #{userType}
ORDER BY s.sanction_created_at_dtm DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(1) FROM tbl_user_m u INNER JOIN tbl_user_sanction_h s ON u.user_sq = s.user_sq LEFT JOIN tbl_company_s c ON u.user_sq = c.user_sq WHERE s.sanction_is_active_yn = 'Y'
AND (u.user_nm LIKE CONCAT('%', #{searchKeyword}, '%') OR u.user_email LIKE CONCAT('%', #{searchKeyword}, '%') OR u.user_phone_num LIKE CONCAT('%', #{searchKeyword}, '%') OR c.company_nm LIKE CONCAT('%', #{searchKeyword}, '%'))
AND u.user_type_cd = #{userType}
